Author: Alexei Podtelezhnikov (Алексей Подтележников) <apodtele@gmail.com>
Date:   Tue Jul 30 21:51:51 2024 -0400

    [truetype/GX] Read points and deltas more carefully.

    Hopefully fixes newly introduced buffer overflows:
      https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=70807
      https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=70809

    * src/truetype/ttgxvar.c (ft_var_readpacked{points,deltas}): Explicitly
    check stream frame limits and modify run counting.

diff --git a/src/truetype/ttgxvar.c b/src/truetype/ttgxvar.c
index 80a9312d9..b4325b1f8 100644
--- a/src/truetype/ttgxvar.c
+++ b/src/truetype/ttgxvar.c
@@ -52,373 +52,347 @@
 #include <freetype/ftlist.h>

 #include "ttpload.h"
 #include "ttgxvar.h"

 #include "tterrors.h"


 #ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT


 #define FT_Stream_FTell( stream )                         \
           (FT_ULong)( (stream)->cursor - (stream)->base )
 #define FT_Stream_SeekSet( stream, off )                               \
           (stream)->cursor =                                           \
             ( (off) < (FT_ULong)( (stream)->limit - (stream)->base ) ) \
                         ? (stream)->base + (off)                       \
                         : (stream)->limit


   /* some macros we need */
 #define FT_fdot14ToFixed( x )                  \
           ( (FT_Fixed)( (FT_ULong)(x) << 2 ) )
 #define FT_intToFixed( i )                      \
           ( (FT_Fixed)( (FT_ULong)(i) << 16 ) )
 #define FT_fdot6ToFixed( i )                    \
           ( (FT_Fixed)( (FT_ULong)(i) << 10 ) )
 #define FT_fixedToInt( x )                          \
           ( (FT_Short)( ( (x) + 0x8000U ) >> 16 ) )
 #define FT_fixedToFdot6( x )                    \
           ( (FT_Pos)( ( (x) + 0x200 ) >> 10 ) )


   /**************************************************************************
    *
    * The macro FT_COMPONENT is used in trace mode.  It is an implicit
    * parameter of the FT_TRACE() and FT_ERROR() macros, used to print/log
    * messages during execution.
    */
 #undef  FT_COMPONENT
 #define FT_COMPONENT  ttgxvar


   /*************************************************************************/
   /*************************************************************************/
   /*****                                                               *****/
   /*****                       Internal Routines                       *****/
   /*****                                                               *****/
   /*************************************************************************/
   /*************************************************************************/


   /**************************************************************************
    *
    * The macro ALL_POINTS is used in `ft_var_readpackedpoints'.  It
    * indicates that there is a delta for every point without needing to
    * enumerate all of them.
    */

   /* ensure that value `0' has the same width as a pointer */
 #define ALL_POINTS  (FT_UShort*)~(FT_PtrDist)0


 #define GX_PT_POINTS_ARE_WORDS      0x80U
 #define GX_PT_POINT_RUN_COUNT_MASK  0x7FU


   /**************************************************************************
    *
    * @Function:
    *   ft_var_readpackedpoints
    *
    * @Description:
    *   Read a set of points to which the following deltas will apply.
    *   Points are packed with a run length encoding.
    *
    * @Input:
    *   stream ::
    *     The data stream.
    *
-   *   size ::
-   *     The size of the table holding the data.
-   *
    * @Output:
    *   point_cnt ::
    *     The number of points read.  A zero value means that
    *     all points in the glyph will be affected, without
    *     enumerating them individually.
    *
    * @Return:
    *   An array of FT_UShort containing the affected points or the
    *   special value ALL_POINTS.
    */
   static FT_UShort*
   ft_var_readpackedpoints( FT_Stream  stream,
-                           FT_ULong   size,
                            FT_UInt   *point_cnt )
   {
     FT_UShort *points = NULL;
     FT_UInt    n;
-    FT_UInt    runcnt;
+    FT_UInt    runcnt, cnt;
     FT_UInt    i, j;
     FT_UShort  first;
     FT_Byte*   p;
     FT_Memory  memory = stream->memory;
     FT_Error   error;


     *point_cnt = 0;

     n = FT_GET_BYTE();
     if ( n == 0 )
       return ALL_POINTS;

     if ( n & GX_PT_POINTS_ARE_WORDS )
     {
       n  &= GX_PT_POINT_RUN_COUNT_MASK;
       n <<= 8;
       n  |= FT_GET_BYTE();
     }

-    if ( n > size )
-    {
-      FT_TRACE1(( "ft_var_readpackedpoints: number of points too large\n" ));
-      return NULL;
-    }
-
-    /* in the nested loops below we increase `i' twice; */
-    /* it is faster to simply allocate one more slot    */
-    /* than to add another test within the loop         */
-    if ( FT_QNEW_ARRAY( points, n + 1 ) )
+    if ( FT_QNEW_ARRAY( points, n ) )
       return NULL;

-    *point_cnt = n;
-
     p     = stream->cursor;
     first = 0;
     i     = 0;
     while ( i < n )
     {
+      if ( p >= stream->limit )
+        goto Fail;
+
       runcnt = FT_NEXT_BYTE( p );
+      cnt    = runcnt & GX_PT_POINT_RUN_COUNT_MASK;
+
+      /* first point not included in run count */
+      cnt++;
+      if ( i + cnt > n )
+        cnt = n - i;
+
       if ( runcnt & GX_PT_POINTS_ARE_WORDS )
       {
-        runcnt     &= GX_PT_POINT_RUN_COUNT_MASK;
-        first      += FT_NEXT_USHORT( p );
-        points[i++] = first;
+        if ( p + 2 * cnt > stream->limit )
+          goto Fail;

-        /* first point not included in run count */
-        for ( j = 0; j < runcnt; j++ )
+        for ( j = 0; j < cnt; j++ )
         {
           first      += FT_NEXT_USHORT( p );
           points[i++] = first;
-          if ( i >= n )
-            break;
         }
       }
       else
       {
-        first      += FT_NEXT_BYTE( p );
-        points[i++] = first;
+        if ( p + cnt > stream->limit )
+          goto Fail;

-        for ( j = 0; j < runcnt; j++ )
+        for ( j = 0; j < cnt; j++ )
         {
           first      += FT_NEXT_BYTE( p );
           points[i++] = first;
-          if ( i >= n )
-            break;
         }
       }
     }

     stream->cursor = p;

+    *point_cnt = n;
+
     return points;
+
+  Fail:
+    FT_TRACE1(( "ft_var_readpackedpoints: invalid table\n" ));
+
+    FT_FREE( points );
+    return NULL;
   }


 #define GX_DT_DELTAS_ARE_ZERO       0x80U
 #define GX_DT_DELTAS_ARE_WORDS      0x40U
 #define GX_DT_DELTA_RUN_COUNT_MASK  0x3FU


   /**************************************************************************
    *
    * @Function:
    *   ft_var_readpackeddeltas
    *
    * @Description:
    *   Read a set of deltas.  These are packed slightly differently than
    *   points.  In particular there is no overall count.
    *
    * @Input:
    *   stream ::
    *     The data stream.
    *
-   *   size ::
-   *     The size of the table holding the data.
-   *
    *   delta_cnt ::
    *     The number of deltas to be read.
    *
    * @Return:
    *   An array of FT_Fixed containing the deltas for the affected
    *   points.  (This only gets the deltas for one dimension.  It will
    *   generally be called twice, once for x, once for y.  When used in
    *   cvt table, it will only be called once.)
    *
    *   We use FT_Fixed to avoid accumulation errors while summing up all
    *   deltas (the rounding to integer values happens as the very last
    *   step).
    */
   static FT_Fixed*
   ft_var_readpackeddeltas( FT_Stream  stream,
-                           FT_ULong   size,
                            FT_UInt    delta_cnt )
   {
